// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit) public {
        newBetLimit = bound(newBetLimit, 0, 1e30);
        // The reference contract: AdjustBetAmounts sets betLimit, then currentDifficulty() returns difficulty (unchanged).
        // The mutant: AdjustBetAmounts sets betLimit, then currentDifficulty() returns betLimit (which is newBetLimit).
        // We compute what the reference should return: difficulty defaults to 0 and is never set, so it stays 0.
        uint256 expectedDifficulty = 0;
        c.AdjustBetAmounts(newBetLimit);
        uint256 returnedDifficulty = c.currentDifficulty();
        assertTrue(returnedDifficulty == expectedDifficulty);
    }
}

